const input = Array.isArray($json) ? $json : [$json];
return input.map((plan) => {
  const days = Number(plan.daysSincePresented ?? 0);
  const value = Number(plan.estimatedValue ?? 0);
  let cadence = 'wait';
  if (days >= 14) cadence = 'coordinator-review';
  else if (days >= 5) cadence = 'approved-follow-up';
  const messageTheme = value >= 5000 ? 'financial-coordinator-next-step' : 'schedule-next-step';
  return { json: { ...plan, cadence, messageTheme, nextAction: cadence === 'wait' ? 'No message today.' : 'Create approved coordinator follow-up task.' } };
});
